import { randomUUID } from 'node:crypto';
import { query, tx, closeDatabase } from '../src/db.js';
import { encryptSecret, generateTotpSecret, hashPassword } from '../src/security.js';
import { ensureSystemAccounts } from '../src/ledger.js';
const username=String(process.env.OWNER_USERNAME||'owner').trim();const password=String(process.env.OWNER_PASSWORD||'');if(password.length<14)throw new Error('OWNER_PASSWORD must contain at least 14 characters');const secret=String(process.env.OWNER_TOTP_SECRET||generateTotpSecret()).replace(/\s/g,'');const hash=await hashPassword(password);const id=randomUUID();
await tx(async client=>{await ensureSystemAccounts(client);const existing=await client.query('SELECT id FROM users WHERE username=$1',[username]);const userId=existing.rows[0]?.id||id;if(existing.rowCount){await client.query(`UPDATE users SET password_hash=$1,mfa_enabled=true,mfa_secret_encrypted=$2,status='ACTIVE',updated_at=now() WHERE id=$3`,[hash,encryptSecret(secret),userId]);}else{await client.query(`INSERT INTO users(id,username,password_hash,status,mfa_enabled,mfa_secret_encrypted,rules_accepted_at) VALUES($1,$2,$3,'ACTIVE',true,$4,now())`,[userId,username,hash,encryptSecret(secret)]);}await client.query(`INSERT INTO user_roles(user_id,role_code,assigned_by) VALUES($1,'OWNER',$1),($1,'SUPERVISOR',$1) ON CONFLICT DO NOTHING`,[userId]);});
const issuer=encodeURIComponent('ASEAN777 Owner');const label=encodeURIComponent(`ASEAN777:${username}`);console.log('Owner account secured. Store this TOTP secret offline and remove it from shell history.');console.log(`TOTP_SECRET=${secret}`);console.log(`OTPAUTH_URI=otpauth://totp/${label}?secret=${secret}&issuer=${issuer}&algorithm=SHA1&digits=6&period=30`);await closeDatabase();
